// Tool: Exportar productos del catálogo al Google Sheet
const apiUrl = $env.CATALOG_API_URL || 'http://cat_backend:3000/api/v1';
const sheetId = $env.GOOGLE_SHEETS_SPREADSHEET_ID;
const apiKey = $env.GOOGLE_SHEETS_API_KEY;
const filtro = $input?.item?.json?.filtroCategoria || '';

try {
  // 1. Login al catálogo
  const loginRes = await this.helpers.httpRequest({
    method: 'POST',
    url: `${apiUrl}/auth/login`,
    body: {
      email: $env.CATALOG_ADMIN_EMAIL || 'admin@catalogo.com',
      password: $env.CATALOG_ADMIN_PASSWORD || 'password'
    },
    json: true
  });
  const token = loginRes.accessToken || loginRes.tokens?.accessToken;

  // 2. Obtener todos los productos
  const productsRes = await this.helpers.httpRequest({
    method: 'GET',
    url: `${apiUrl}/products?limit=1000&include=category,brand`,
    headers: { 'Authorization': `Bearer ${token}` },
    json: true
  });
  let products = productsRes.data || productsRes;
  if (!Array.isArray(products)) products = [];

  // 3. Filtrar por categoría si se pidió
  if (filtro) {
    products = products.filter(p => {
      const catName = p.category?.name || '';
      return catName.toLowerCase().includes(filtro.toLowerCase());
    });
  }

  if (products.length === 0) {
    return { result: filtro ? `No se encontraron productos en la categoría "${filtro}"` : 'No hay productos en el catálogo para exportar' };
  }

  // 4. Formatear filas para el Sheet
  const header = ['Nombre', 'Precio', 'Precio Oferta', 'Categoría', 'Marca', 'Descripción', 'Stock', 'Estado', 'SEO Título', 'SEO Descripción', 'SEO Keywords', 'URL Imagen'];
  const rows = products.map(p => [
    p.name || '',
    p.price || 0,
    p.salePrice || '',
    p.category?.name || '',
    p.brand?.name || '',
    p.description || '',
    p.stock != null ? p.stock : '',
    p.isActive ? 'activo' : 'inactivo',
    p.seoTitle || '',
    p.seoDescription || '',
    p.seoKeywords || '',
    (p.images && p.images[0]?.url) || p.imageUrl || ''
  ]);

  // 5. Limpiar hoja "Productos" primero
  await this.helpers.httpRequest({
    method: 'POST',
    url: `https://sheets.googleapis.com/v4/spreadsheets/${sheetId}/values/Productos:clear?key=${apiKey}`,
    body: {},
    json: true
  });

  // 6. Escribir header + filas
  const allRows = [header, ...rows];
  await this.helpers.httpRequest({
    method: 'PUT',
    url: `https://sheets.googleapis.com/v4/spreadsheets/${sheetId}/values/Productos!A1?valueInputOption=USER_ENTERED&key=${apiKey}`,
    body: {
      range: 'Productos!A1',
      majorDimension: 'ROWS',
      values: allRows
    },
    json: true
  });

  return { result: `✅ ${products.length} productos exportados al Sheet${filtro ? ` (filtro: ${filtro})` : ''}. Columnas: ${header.join(', ')}` };

} catch (error) {
  return { result: `❌ Error al exportar: ${error.message}` };
}

// Tool: Importar productos del Google Sheet al catálogo
const apiUrl = $env.CATALOG_API_URL || 'http://cat_backend:3000/api/v1';
const sheetId = $env.GOOGLE_SHEETS_SPREADSHEET_ID;
const apiKey = $env.GOOGLE_SHEETS_API_KEY;
const filtro = $input?.item?.json?.filtroCategoria || '';

try {
  // 1. Leer filas del Sheet
  const sheetRes = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://sheets.googleapis.com/v4/spreadsheets/${sheetId}/values/Productos!A1:L1000?key=${apiKey}`,
    json: true
  });
  const allRows = sheetRes.values || [];
  if (allRows.length < 2) {
    return { result: 'El Sheet está vacío o solo tiene encabezados. No hay nada que importar.' };
  }

  const headers = allRows[0];
  let dataRows = allRows.slice(1);

  // Filtrar por categoría si se pidió
  const catIdx = headers.findIndex(h => h.toLowerCase().includes('categor'));
  if (filtro && catIdx >= 0) {
    dataRows = dataRows.filter(row => {
      const cat = (row[catIdx] || '').toLowerCase();
      return cat.includes(filtro.toLowerCase());
    });
  }

  if (dataRows.length === 0) {
    return { result: filtro ? `No se encontraron filas con categoría "${filtro}" en el Sheet.` : 'No hay filas de datos en el Sheet.' };
  }

  // 2. Login al catálogo
  const loginRes = await this.helpers.httpRequest({
    method: 'POST',
    url: `${apiUrl}/auth/login`,
    body: {
      email: $env.CATALOG_ADMIN_EMAIL || 'admin@catalogo.com',
      password: $env.CATALOG_ADMIN_PASSWORD || 'password'
    },
    json: true
  });
  const token = loginRes.accessToken || loginRes.tokens?.accessToken;

  // 3. Obtener categorías y marcas para mapear nombres a IDs
  const [catsRes, brandsRes] = await Promise.all([
    this.helpers.httpRequest({
      method: 'GET',
      url: `${apiUrl}/categories`,
      headers: { 'Authorization': `Bearer ${token}` },
      json: true
    }),
    this.helpers.httpRequest({
      method: 'GET',
      url: `${apiUrl}/brands`,
      headers: { 'Authorization': `Bearer ${token}` },
      json: true
    })
  ]);
  const categories = catsRes.data || catsRes || [];
  const brands = brandsRes.data || brandsRes || [];

  // Mapear columnas por índice
  const colMap = {};
  headers.forEach((h, i) => {
    const hl = h.toLowerCase().trim();
    if (hl.includes('nombre') || hl === 'name') colMap.name = i;
    else if (hl.includes('precio oferta') || hl.includes('sale')) colMap.salePrice = i;
    else if (hl.includes('precio') || hl === 'price') colMap.price = i;
    else if (hl.includes('categor')) colMap.category = i;
    else if (hl.includes('marca') || hl.includes('brand')) colMap.brand = i;
    else if (hl.includes('descrip')) colMap.description = i;
    else if (hl.includes('stock') || hl.includes('inventar')) colMap.stock = i;
    else if (hl.includes('estado') || hl.includes('status')) colMap.status = i;
    else if (hl.includes('seo tít') || hl.includes('seo titulo')) colMap.seoTitle = i;
    else if (hl.includes('seo desc')) colMap.seoDescription = i;
    else if (hl.includes('seo key') || hl.includes('keyword')) colMap.seoKeywords = i;
    else if (hl.includes('imagen') || hl.includes('image') || hl.includes('url')) colMap.imageUrl = i;
  });

  let success = 0;
  let errors = 0;
  const errorDetails = [];

  // 4. Crear cada producto
  for (const row of dataRows) {
    try {
      const name = (row[colMap.name] || '').trim();
      const price = parseFloat(row[colMap.price]) || 0;
      if (!name || price <= 0) {
        errors++;
        errorDetails.push(`"${name || '(vacío)'}" - sin nombre o precio`);
        continue;
      }

      const catName = (row[colMap.category] || '').trim();
      const brandName = (row[colMap.brand] || '').trim();
      const cat = categories.find(c => c.name.toLowerCase() === catName.toLowerCase());
      const brand = brands.find(b => b.name.toLowerCase() === brandName.toLowerCase());

      const statusVal = (row[colMap.status] || 'activo').toLowerCase();

      const productBody = {
        name: name,
        price: price,
        salePrice: row[colMap.salePrice] ? parseFloat(row[colMap.salePrice]) : null,
        categoryId: cat?.id || null,
        brandId: brand?.id || null,
        description: (row[colMap.description] || '').trim(),
        stock: row[colMap.stock] ? parseInt(row[colMap.stock]) : null,
        isActive: statusVal !== 'inactivo',
        seoTitle: (row[colMap.seoTitle] || '').trim() || null,
        seoDescription: (row[colMap.seoDescription] || '').trim() || null,
        seoKeywords: (row[colMap.seoKeywords] || '').trim() || null,
        imageUrl: (row[colMap.imageUrl] || '').trim() || null,
        showPrice: true
      };

      await this.helpers.httpRequest({
        method: 'POST',
        url: `${apiUrl}/products`,
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        },
        body: productBody,
        json: true
      });
      success++;
    } catch (err) {
      errors++;
      const name = (row[colMap.name] || '(vacío)').trim();
      errorDetails.push(`"${name}" - ${err.message}`);
    }
  }

  let result = `✅ ${success} productos importados, ${errors} errores`;
  if (errorDetails.length > 0) {
    result += `\n\nErrores:\n${errorDetails.slice(0, 10).join('\n')}`;
    if (errorDetails.length > 10) result += `\n...y ${errorDetails.length - 10} más`;
  }
  return { result };

} catch (error) {
  return { result: `❌ Error al importar: ${error.message}` };
}

