// Procesar fila del Sheet y sincronizar con el catálogo
const apiUrl = $env.CATALOG_API_URL || 'http://cat_backend:3000/api/v1';
const token = $('Login API (Auto-Sync)').first().json.accessToken || $('Login API (Auto-Sync)').first().json.tokens?.accessToken;
const row = $('Sheet: Fila nueva/editada').first().json;

// Mapear campos del Sheet (flexible con nombres de columna)
const nombre = row['Nombre'] || row['nombre'] || row['Name'] || row['name'] || '';
const precio = parseFloat(row['Precio'] || row['precio'] || row['Price'] || 0);
const precioOferta = row['Precio Oferta'] || row['precio_oferta'] || row['Sale Price'] || null;
const categoria = row['Categoría'] || row['categoria'] || row['Category'] || '';
const marca = row['Marca'] || row['marca'] || row['Brand'] || '';
const descripcion = row['Descripción'] || row['descripcion'] || row['Description'] || '';
const stock = row['Stock'] || row['stock'] || null;
const estado = (row['Estado'] || row['estado'] || row['Status'] || 'activo').toLowerCase();

if (!nombre || nombre.trim() === '') {
  return [{ json: { status: 'skipped', reason: 'Fila sin nombre de producto' } }];
}

if (precio <= 0) {
  return [{ json: { status: 'skipped', reason: `"${nombre}" sin precio válido` } }];
}

try {
  // Obtener categorías y marcas para mapear nombres → IDs
  const [catsRes, brandsRes] = await Promise.all([
    $fetch({
      method: 'GET',
      url: `${apiUrl}/categories`,
      headers: { 'Authorization': `Bearer ${token}` },
      returnFullResponse: false
    }),
    $fetch({
      method: 'GET',
      url: `${apiUrl}/brands`,
      headers: { 'Authorization': `Bearer ${token}` },
      returnFullResponse: false
    })
  ]).catch(() => [null, null]);

  // Fallback: usar this.helpers.httpRequest
  let categories = [];
  let brands = [];

  try {
    const catsData = await this.helpers.httpRequest({
      method: 'GET',
      url: `${apiUrl}/categories`,
      headers: { 'Authorization': `Bearer ${token}` },
      json: true
    });
    categories = catsData.data || catsData || [];
  } catch(e) { categories = []; }

  try {
    const brandsData = await this.helpers.httpRequest({
      method: 'GET',
      url: `${apiUrl}/brands`,
      headers: { 'Authorization': `Bearer ${token}` },
      json: true
    });
    brands = brandsData.data || brandsData || [];
  } catch(e) { brands = []; }

  const cat = categories.find(c => c.name.toLowerCase() === categoria.toLowerCase().trim());
  const brand = brands.find(b => b.name.toLowerCase() === marca.toLowerCase().trim());

  // Buscar si el producto ya existe por nombre
  const searchRes = await this.helpers.httpRequest({
    method: 'GET',
    url: `${apiUrl}/products?search=${encodeURIComponent(nombre.trim())}&limit=5`,
    headers: { 'Authorization': `Bearer ${token}` },
    json: true
  });
  const existingProducts = searchRes.data || searchRes || [];
  const existing = existingProducts.find(p => p.name.toLowerCase().trim() === nombre.toLowerCase().trim());

  const productBody = {
    name: nombre.trim(),
    price: precio,
    salePrice: precioOferta ? parseFloat(precioOferta) : null,
    categoryId: cat?.id || null,
    brandId: brand?.id || null,
    description: descripcion.trim() || null,
    stock: stock ? parseInt(stock) : null,
    isActive: estado !== 'inactivo',
    showPrice: true
  };

  if (existing) {
    // Actualizar producto existente
    await this.helpers.httpRequest({
      method: 'PATCH',
      url: `${apiUrl}/products/${existing.id}`,
      headers: {
        'Authorization': `Bearer ${token}`,
        'Content-Type': 'application/json'
      },
      body: productBody,
      json: true
    });
    return [{ json: { status: 'updated', product: nombre.trim(), id: existing.id } }];
  } else {
    // Crear producto nuevo
    const created = await this.helpers.httpRequest({
      method: 'POST',
      url: `${apiUrl}/products`,
      headers: {
        'Authorization': `Bearer ${token}`,
        'Content-Type': 'application/json'
      },
      body: productBody,
      json: true
    });
    return [{ json: { status: 'created', product: nombre.trim(), id: created.id } }];
  }

} catch (error) {
  return [{ json: { status: 'error', product: nombre.trim(), error: error.message } }];
}

